            Some(SyntaxStruct::DataDeclarationSyntax)
                | Some(SyntaxStruct::TypedefDeclarationSyntax)
                | Some(SyntaxStruct::ForwardTypedefDeclarationSyntax)
                | Some(SyntaxStruct::NetDeclarationSyntax)
                | Some(SyntaxStruct::UserDefinedNetDeclarationSyntax)
                | Some(SyntaxStruct::NetTypeDeclarationSyntax)
                | Some(SyntaxStruct::PackageImportDeclarationSyntax)
                | Some(SyntaxStruct::PackageExportDeclarationSyntax)
