                | Some(SyntaxStruct::ModportDeclarationSyntax)
                | Some(SyntaxStruct::DefaultSkewItemSyntax)
                | Some(SyntaxStruct::ClockingItemSyntax)
                | Some(SyntaxStruct::ClockingDeclarationSyntax)
                | Some(SyntaxStruct::DefaultClockingReferenceSyntax)
                | Some(SyntaxStruct::DefaultDisableDeclarationSyntax)
                | Some(SyntaxStruct::DPIImportSyntax)
                | Some(SyntaxStruct::DPIExportSyntax)
