/// Any node deriving from slang's abstract `ArgumentSyntax`.
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub enum ArgumentSyntax<'t> {
    /// A [`EmptyArgumentSyntax`].
    EmptyArgument(EmptyArgumentSyntax<'t>),
    /// A [`OrderedArgumentSyntax`].
    OrderedArgument(OrderedArgumentSyntax<'t>),
    /// A [`NamedArgumentSyntax`].
    NamedArgument(NamedArgumentSyntax<'t>),
}

impl<'t> AstNode<'t> for ArgumentSyntax<'t> {
    fn can_cast(kind: SyntaxKind) -> bool {
        matches!(
            kind.syntax_struct(),
            Some(SyntaxStruct::EmptyArgumentSyntax)
                | Some(SyntaxStruct::OrderedArgumentSyntax)
                | Some(SyntaxStruct::NamedArgumentSyntax)
        )
    }

    fn cast(node: Node<'t>) -> Option<Self> {
        if let Some(n) = <EmptyArgumentSyntax<'t>>::cast(node) {
            return Some(Self::EmptyArgument(n));
        }
        if let Some(n) = <OrderedArgumentSyntax<'t>>::cast(node) {
            return Some(Self::OrderedArgument(n));
        }
        if let Some(n) = <NamedArgumentSyntax<'t>>::cast(node) {
            return Some(Self::NamedArgument(n));
        }
        None
    }

    fn syntax(&self) -> Node<'t> {
        match self {
            Self::EmptyArgument(n) => n.syntax(),
            Self::OrderedArgument(n) => n.syntax(),
            Self::NamedArgument(n) => n.syntax(),
        }
    }
}

impl core::fmt::Debug for ArgumentSyntax<'_> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        core::fmt::Debug::fmt(&self.syntax(), f)
    }
}

impl<'t> From<EmptyArgumentSyntax<'t>> for ArgumentSyntax<'t> {
    fn from(n: EmptyArgumentSyntax<'t>) -> Self {
        Self::EmptyArgument(n)
    }
}

impl<'t> From<OrderedArgumentSyntax<'t>> for ArgumentSyntax<'t> {
    fn from(n: OrderedArgumentSyntax<'t>) -> Self {
        Self::OrderedArgument(n)
    }
}

impl<'t> From<NamedArgumentSyntax<'t>> for ArgumentSyntax<'t> {
    fn from(n: NamedArgumentSyntax<'t>) -> Self {
        Self::NamedArgument(n)
    }
}

/// Typed view of a [`Node`] whose struct is [`SyntaxStruct::EmptyArgumentSyntax`].
///
/// Kinds: EmptyArgument.
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub struct EmptyArgumentSyntax<'t> {
    node: Node<'t>,
}

impl<'t> AstNode<'t> for EmptyArgumentSyntax<'t> {
    fn can_cast(kind: SyntaxKind) -> bool {
        kind.syntax_struct() == Some(SyntaxStruct::EmptyArgumentSyntax)
    }

    fn cast(node: Node<'t>) -> Option<Self> {
        Self::can_cast(node.kind()).then_some(Self { node })
    }

    fn syntax(&self) -> Node<'t> {
        self.node
    }
}

impl core::fmt::Debug for EmptyArgumentSyntax<'_> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        core::fmt::Debug::fmt(&self.node, f)
    }
}

impl<'t> EmptyArgumentSyntax<'t> {
    /// Member `placeholder` (child 0).
    pub fn placeholder(&self) -> Option<Token<'t>> {
        self.node.member_token(0)
    }
}

#[cfg(test)]
impl<'t> EmptyArgumentSyntax<'t> {
    pub(crate) fn touch_members(&self) {
        let _ = self.placeholder();
    }
}

