/// Any node deriving from slang's abstract `SelectorSyntax`.
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub enum SelectorSyntax<'t> {
    /// A [`BitSelectSyntax`].
    BitSelect(BitSelectSyntax<'t>),
    /// A [`RangeSelectSyntax`].
    RangeSelect(RangeSelectSyntax<'t>),
}

impl<'t> AstNode<'t> for SelectorSyntax<'t> {
    fn can_cast(kind: SyntaxKind) -> bool {
        matches!(
            kind.syntax_struct(),
            Some(SyntaxStruct::BitSelectSyntax) | Some(SyntaxStruct::RangeSelectSyntax)
        )
    }

    fn cast(node: Node<'t>) -> Option<Self> {
        if let Some(n) = <BitSelectSyntax<'t>>::cast(node) {
            return Some(Self::BitSelect(n));
        }
        if let Some(n) = <RangeSelectSyntax<'t>>::cast(node) {
            return Some(Self::RangeSelect(n));
        }
        None
    }

    fn syntax(&self) -> Node<'t> {
        match self {
            Self::BitSelect(n) => n.syntax(),
            Self::RangeSelect(n) => n.syntax(),
        }
    }
}

impl core::fmt::Debug for SelectorSyntax<'_> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        core::fmt::Debug::fmt(&self.syntax(), f)
    }
}

impl<'t> From<BitSelectSyntax<'t>> for SelectorSyntax<'t> {
    fn from(n: BitSelectSyntax<'t>) -> Self {
        Self::BitSelect(n)
    }
}

impl<'t> From<RangeSelectSyntax<'t>> for SelectorSyntax<'t> {
    fn from(n: RangeSelectSyntax<'t>) -> Self {
        Self::RangeSelect(n)
    }
}

